## Steps

### Step 1: Add ParseContext and ParserPool to adapter.rs

Define the core-owned parsing infrastructure alongside the existing trait:

```rust
use std::time::Duration;
use tree_sitter::{Language, Parser, Tree};
use crate::error::SutraError;

pub struct ParseContext<'a> {
    pub source: &'a [u8],
    pub tree: &'a Tree,
    pub file_path: &'a str,
}

pub struct ParserPool {
    parsers: HashMap<String, Parser>,
    timeout_micros: u64,
}

impl ParserPool {
    pub fn new(timeout: Duration) -> Self {
        Self {
            parsers: HashMap::new(),
            timeout_micros: timeout.as_micros() as u64,
        }
    }

    pub fn parse_with(
        &mut self,
        adapter: &dyn LanguageAdapter,
        source: &str,
        file_path: &str,
    ) -> Result<ParseResult> {
        let lang_id = adapter.language_id().to_string();
        let parser = self.parsers.entry(lang_id).or_insert_with(|| {
            let mut p = Parser::new();
            p.set_language(&adapter.grammar())
                .expect("adapter returned invalid grammar");
            p.set_timeout_micros(self.timeout_micros);
            p
        });

        let tree = parser
            .parse(source, None)
            .ok_or_else(|| SutraError::Parse("tree-sitter parse timed out or returned no tree".into()))?;

        let ctx = ParseContext {
            source: source.as_bytes(),
            tree: &tree,
            file_path,
        };
        adapter.parse(&ctx)
    }
}
```

