Add parser pooling test:
```rust
#[test]
fn parser_pool_reuses_parser() {
    let mut pool = ParserPool::new(Duration::from_secs(5));
    let adapter = RustAdapter;

    let r1 = pool.parse_with(&adapter, "fn a() {}", "a.rs").unwrap();
    assert!(r1.parsed_ok);

    let r2 = pool.parse_with(&adapter, "fn b() {}", "b.rs").unwrap();
    assert!(r2.parsed_ok);

    // Pool should contain exactly one parser (for "rust")
    assert_eq!(pool.parsers.len(), 1);
}
```

Add timeout test:
```rust
#[test]
fn timeout_rejects_pathological_input() {
    let mut pool = ParserPool::new(Duration::from_micros(1));  // 1μs — will always timeout
    let adapter = RustAdapter;

    let result = pool.parse_with(&adapter, "fn valid() {}", "test.rs");
    assert!(result.is_err());
}
